import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused kernel for matmul + dropout + mean + softmax
fused_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <curand_kernel.h>

__global__ void fused_op_kernel(
    const float* input, const float* weight, const float* bias,
    float* output, int in_features, int out_features, int batch_size,
    float dropout_p, bool training, unsigned long long seed
) {
    int row = blockIdx.x;
    int tid = threadIdx.x;

    extern __shared__ float shared[];

    // Matmul + bias computation
    float sum = 0.0f;
    for (int i = tid; i < in_features; i += blockDim.x) {
        sum += input[row * in_features + i] * weight[i * out_features + blockIdx.y];
    }
    shared[tid] = sum;
    __syncthreads();

    // Parallel reduction for matmul result
    for (int stride = blockDim.x/2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shared[tid] += shared[tid + stride];
        }
        __syncthreads();
    }

    float val = shared[0] + bias[blockIdx.y];

    // Dropout + mean + softmax logic
    if (tid == 0) {
        curandStatePhilox4_32_10_t state;
        curand_init(seed, row, 0, &state);
        float rand_val = curand_uniform(&state);

        if (training && rand_val < dropout_p) val = 0.0f;
        else if (training) val /= (1.0f - dropout_p);

        atomicAdd(&output[row], val / out_features);

        // Softmax on single element is 1.0
        __syncthreads();
        if (blockIdx.y == 0) output[row] = 1.0f;
    }
}

torch::Tensor fused_op_cuda(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    float dropout_p, bool training
) {
    auto batch_size = input.size(0);
    auto out_features = weight.size(1);
    auto output = torch::zeros({batch_size, 1}, input.options());

    unsigned long long seed = std::chrono::system_clock::now().time_since_epoch().count();

    dim3 blocks(batch_size, out_features);
    fused_op_kernel<<<blocks, 256, 256*sizeof(float)>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        input.size(1),
        out_features,
        batch_size,
        dropout_p,
        training,
        seed
    );

    return output;
}
"""

fused_kernel_cpp = "torch::Tensor fused_op_cuda(torch::Tensor, torch::Tensor, torch::Tensor, float, bool);"

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_source,
    functions=['fused_op_cuda'],
    verbose=True,
    extra_cuda_cflags=["-D__CUDA_NO_HALF_OPERATORS__"]
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, dropout_p):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))
        self.dropout_p = dropout_p
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        nn.init.zeros_(self.bias)

    def forward(self, x):
        return fused_op.fused_op_cuda(
            x, 
            self.weight, 
            self.bias,
            self.dropout_p,
            self.training
        )
